// No tracked HTML, CSS or JS/MJS producer declares its own --bg, --ink or --acc outside the theme
// files (docs/THEME.md §11, step 4). The population is `git ls-files`; content is the working tree.
//
// A generated artefact counts only through its generator: every file under docsite/pages/ is
// bin/docsite-build.mjs output (rendered through lib/docsite-page.mjs, or a byte copy of
// docsite/imported/ that its --check holds equal), and any other file counts through the tracked
// generator that its first 1 KB, or its docsite/manifest.json note, names with "Generated by <path>".
// A generator that is not tracked here gives no exemption, and a generator exempts only what it
// writes: bin/docsite-build.mjs writes docsite/pages/ and copies docsite/imported/ there byte for
// byte, so its name in an imported source's header is a claim, not an exemption.
//
// A page's <style id="house-css"> block is a copy bin/house-css.mjs writes and --check holds fresh, so
// it is read past; the last test requires every page that carries one to be a registered copy.
//
// admin/static/theme.css is not a theme file for this purpose: its vocabulary is --cw-*, and a --bg
// appearing there would be a second palette.

import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO = join(dirname(fileURLToPath(import.meta.url)), '..', '..');

const PRODUCER = /\.(html?|css|m?js|cjs)$/;
const ARTEFACT = /\.(html?|css)$/;
const DECLARES = /(?<![\w-])--(?:bg|ink|acc)['"]?\s*:/;
const HEADER_GENERATOR = /Generated by ((?:[\w.-]+\/)*[\w.-]+\.m?js)\b/;
const HEADER_WINDOW = 1024;
const HOUSE_REGION = /<style id="house-css">[\s\S]*?<\/style>/g;

// Where a generator writes, for a generator that does not write everything that names it.
const WRITES = { 'bin/docsite-build.mjs': /^docsite\/pages\// };
const writes = (generator, path) => !WRITES[generator] || WRITES[generator].test(path);

const THEME_FILES = [
  'admin/static/panel.css', 'admin/static/panel-light.css', /^admin\/static\/panel-cvd[\w-]*\.css$/,
  'lib/brand-tokens.mjs', 'lib/house-css.mjs', 'admin/static/house.css',
];
const isTheme = (p) => THEME_FILES.some((t) => (typeof t === 'string' ? t === p : t.test(p)));

// Tests that cannot test what they test without declaring a token.
const FIXTURES = {
  'admin/test/a11y-attest-route.test.mjs': 'its stylesheet fixture needs a --bg ground and an --ink to measure contrast against',
  'monitor/test/a11y-attestations.test.mjs': 'its stylesheet fixture needs a --bg ground and an --ink to measure contrast against',
  'lib/test/md-view.test.mjs': 'asserts that scopeCss() moves a :root declaration under its container, so it writes one',
  'bin/test/house-css-copy.test.mjs': 'stales a generated copy by rewriting its --bg, to prove --check catches the drift',
};

// Every producer that declares its own palette today, each against its THEME.md §11 row. Remove an
// entry when its surface moves onto houseCss(); the test fails until you do.
const PENDING = {
};

// Producers that declare the names but no palette of their own: the values are lib/brand-tokens.mjs
// interpolated, or a copy a parity test holds equal to it (THEME.md §11, "Follows the house palette").
// Each .mjs one must import the tokens, which the last test below checks.
const DERIVED = {
  'bin/taxonomy-render.mjs': 'interpolates LIGHT and DARK under its own --page and --ink names',
  'bin/scanner-taxonomy-render.mjs': 'interpolates LIGHT and DARK under its own --page and --ink names',
  'bin/taxonomy-structure.mjs': 'interpolates LIGHT on :root',
  'lib/docsite-page.mjs': 'PAPER_CSS, plus the print override that swaps in #fff grounds for paper (THEME.md §2.3)',
  'docsite/editor/editor.css': 'restates DARK under its data-theme toggle; bin/test/brand-tokens-parity.test.mjs holds the copy equal',
  'docsite/imported/commitwork-coverage-survey.html': 'a recovered static page the docsite build copies to pages/: PAPER_CSS and the shell\'s print override verbatim, its own names aliased onto them',
};

// The token values a derived page restates outside PAPER_CSS, each held equal to lib/brand-tokens.mjs
// below. Any other colour literal on a custom property there is a stale second copy.
const RESTATED = {
  'docsite/imported/commitwork-coverage-survey.html': { '--warn': ['LIGHT_SEMANTIC', 'part'] },
};
// docsite/imported/taxonomy-proposed.html left this list on 2026-09-30: it is a draft document, kept in
// the private docsite root with the generator that writes it, so no tracked copy remains to check.

const REASON = /^§12 item (\d+): \S/;

function manifestGenerators(readText) {
  const text = readText('docsite/manifest.json');
  if (text === null) return new Map();
  const manifest = JSON.parse(text);
  const docs = Array.isArray(manifest) ? manifest : manifest.docs;
  assert.ok(Array.isArray(docs), 'docsite/manifest.json has no docs array');
  const out = new Map();
  for (const d of docs) {
    const m = d && typeof d.source === 'string' && typeof d.note === 'string' && HEADER_GENERATOR.exec(d.note);
    if (m) out.set(`docsite/${d.source}`, m[1]);
  }
  return out;
}

function scan(files, readText) {
  const tracked = new Set(files);
  const fromManifest = manifestGenerators(readText);
  const declaring = [];
  const generated = new Map();
  let read = 0;
  for (const path of files) {
    if (!PRODUCER.test(path) || isTheme(path)) continue;
    const raw = readText(path);
    if (raw === null) continue;
    read++;
    const text = ARTEFACT.test(path) ? raw.replace(HOUSE_REGION, '') : raw;
    if (!DECLARES.test(text)) continue;
    if (path.startsWith('docsite/pages/')) { generated.set(path, 'bin/docsite-build.mjs'); continue; }
    const header = ARTEFACT.test(path) && HEADER_GENERATOR.exec(text.slice(0, HEADER_WINDOW));
    const generator = (header && header[1]) || (ARTEFACT.test(path) && fromManifest.get(path));
    if (generator && tracked.has(generator) && writes(generator, path)) { generated.set(path, generator); continue; }
    declaring.push(path);
  }
  return { declaring, generated, read };
}

function audit({ declaring }, files, allowed) {
  const tracked = new Set(files);
  const set = new Set(declaring);
  return {
    unlisted: declaring.filter((p) => !(p in allowed)),
    spent: Object.keys(allowed).filter((p) => !set.has(p)).map((p) => `${p}${tracked.has(p) ? '' : ' (no longer tracked)'}`),
  };
}

const trackedFiles = () => execFileSync('git', ['-C', REPO, 'ls-files', '-z'], { encoding: 'utf8', maxBuffer: 256 * 1024 * 1024 })
  .split('\0').filter(Boolean);

const readWorktree = (path) => {
  try { return readFileSync(join(REPO, path), 'utf8'); } catch (e) { if (e.code === 'ENOENT') return null; throw e; }
};

const ALLOWED = { ...PENDING, ...FIXTURES, ...DERIVED };

describe('no second palette', () => {
  const files = trackedFiles();
  const result = scan(files, readWorktree);

  test('the detector sees real declarations and misses near-misses', () => {
    const dash = '--';
    for (const s of [`:root{${dash}bg:#000}`, `a{ ${dash}ink : red }`, `html[data-mode=dark]{${dash}acc:#c9a227}`, `{ '${dash}bg': '#fff' }`]) {
      assert.match(s, DECLARES, s);
    }
    for (const s of [`color:var(${dash}ink)`, `${dash}acc2:#000`, `${dash}cw-bg:#000`, `${dash}bg-2:#000`, `${dash}inkwell:x`, `x${dash}bg:1`]) {
      assert.doesNotMatch(s, DECLARES, s);
    }
    for (const theme of ['admin/static/panel.css', 'admin/static/panel-light.css', 'lib/brand-tokens.mjs']) {
      assert.match(readWorktree(theme), DECLARES, `${theme} no longer matches the detector, so it may be matching nothing`);
    }
    assert.ok(result.read > 500, `read only ${result.read} tracked producers`);
    assert.ok(result.declaring.length >= Object.keys(PENDING).length / 2, `found only ${result.declaring.length} declaring files`);
  });

  test('a planted palette in an unlisted file is reported, and a pending file that stopped is spent', () => {
    const dash = '--';
    const planted = {
      'planted/new-report.mjs': `const CSS = \`:root{${dash}bg:#101216}\`;`,
      'bin/projectstatus.mjs': 'const CSS = ":root{}";',
      'docsite/pages/x/index.html': `<style>:root{${dash}ink:#111}</style>`,
      'planted/gen.html': `<!-- Generated by planted/gen.mjs -->\n<style>:root{${dash}acc:#000}</style>`,
      'planted/gen.mjs': 'export {};',
      'planted/orphan.html': `<!-- Generated by planted/nowhere.mjs -->\n<style>:root{${dash}acc:#000}</style>`,
      'docsite/imported/copied.html': `<!-- Generated by bin/docsite-build.mjs -->\n<style>:root{${dash}acc:#000}</style>`,
      'bin/docsite-build.mjs': 'export {};',
    };
    const fake = Object.keys(planted);
    const got = scan(fake, (p) => planted[p] ?? null);
    assert.deepEqual(got.declaring.sort(), ['docsite/imported/copied.html', 'planted/new-report.mjs', 'planted/orphan.html']);
    assert.deepEqual([...got.generated.keys()].sort(), ['docsite/pages/x/index.html', 'planted/gen.html']);
    const { unlisted, spent } = audit(got, fake, { 'bin/projectstatus.mjs': PENDING['bin/projectstatus.mjs'], 'planted/gone.mjs': 'x' });
    assert.deepEqual(unlisted.sort(), ['docsite/imported/copied.html', 'planted/new-report.mjs', 'planted/orphan.html']);
    assert.deepEqual(spent.sort(), ['bin/projectstatus.mjs', 'planted/gone.mjs (no longer tracked)']);
  });

  test('no tracked producer declares --bg, --ink or --acc outside the theme files and the pending list', () => {
    const { unlisted } = audit(result, files, ALLOWED);
    assert.deepEqual(unlisted, [],
      `these declare their own palette: ${unlisted.join(', ')}. Take the tokens from houseCss() (lib/house-css.mjs) `
      + 'or link /static/house.css, and write layout rules against var(--bg), var(--ink) and var(--acc)');
  });

  test('every pending entry still declares one — a fixed surface spends its exception', () => {
    const { spent } = audit(result, files, ALLOWED);
    assert.deepEqual(spent, [], `these no longer declare a palette; delete their entries: ${spent.join(', ')}`);
  });

  test('every pending entry is a known deviation that THEME.md §12 names', () => {
    if (!Object.keys(PENDING).length) return;
    const theme = readWorktree('docs/THEME.md');
    assert.notEqual(theme, null, 'docs/THEME.md is missing');
    const start = theme.indexOf('\n## 12.');
    assert.ok(start >= 0, 'THEME.md has no §12 to check against');
    const end = theme.indexOf('\n## ', start + 1);
    const s12 = end < 0 ? theme.slice(start) : theme.slice(start, end);
    for (const [path, reason] of Object.entries(PENDING)) {
      const m = REASON.exec(reason);
      assert.ok(m, `${path}: reason must read '§12 item <n>: <why>' — got "${reason}"`);
      const at = s12.indexOf(`\n${m[1]}. `);
      assert.ok(at >= 0, `${path}: THEME.md §12 has no item ${m[1]}`);
      const next = s12.slice(at + 1).search(/\n\d+\. /);
      const item = s12.slice(at, next < 0 ? undefined : at + 1 + next);
      assert.ok(item.includes(path.split('/').pop()), `${path}: THEME.md §12 item ${m[1]} does not name it`);
    }
  });

  test('every derived producer takes its values from lib/brand-tokens.mjs', async () => {
    const { PAPER_CSS } = await import('../../lib/brand-tokens.mjs');
    for (const path of Object.keys(DERIVED).filter((p) => p.endsWith('.html'))) {
      assert.ok((readWorktree(path) ?? '').includes(PAPER_CSS), `${path} is listed as derived but does not carry PAPER_CSS verbatim`);
    }
    for (const path of Object.keys(DERIVED).filter((p) => p.endsWith('.mjs'))) {
      assert.match(readWorktree(path) ?? '', /from '(?:\.\.\/)*(?:lib\/|\.\/)brand-tokens\.mjs'/, `${path} is listed as derived but does not import lib/brand-tokens.mjs`);
    }
  });

  test('a derived page restates no colour outside PAPER_CSS but the values RESTATED holds to the tokens', async () => {
    const tokens = await import('../../lib/brand-tokens.mjs');
    const { CSS: SHELL } = await import('../../lib/docsite-page.mjs');
    const print = /@media print\{\s*:root\{[^}]*\}/.exec(SHELL);
    assert.ok(print, 'lib/docsite-page.mjs has no print override to read past');
    const LITERAL = /(--[\w-]+)\s*:\s*(#[0-9a-f]{3,8}\b|rgba?\([^)]*\))/gi;
    for (const path of Object.keys(DERIVED).filter((p) => p.endsWith('.html'))) {
      const rest = (readWorktree(path) ?? '').replace(tokens.PAPER_CSS, '').replace(print[0], '');
      const want = RESTATED[path] || {};
      const found = [...rest.matchAll(LITERAL)].map((m) => [m[1], m[2]]);
      assert.deepEqual(found.map(([n]) => n).sort(), Object.keys(want).sort(), `${path} restates colours the tokens do not hold it to`);
      for (const [name, value] of found) {
        const [set, key] = want[name];
        assert.equal(value.toLowerCase(), tokens[set][key].toLowerCase(), `${path} ${name} is not ${set}.${key}`);
      }
    }
  });

  test('every page that carries a house-css block is a copy bin/house-css.mjs registers and checks', async () => {
    const { COPIES } = await import('../house-css.mjs');
    const registered = new Set(COPIES.map((c) => c.path()));
    const carriers = files.filter((p) => ARTEFACT.test(p) && (readWorktree(p) ?? '').includes('<style id="house-css">'));
    // The floor comes from the registry, not a count: every registered page the tree tracks must
    // carry the block. A fixed number went stale when pages moved to the private root and a sibling repo.
    const registeredPages = COPIES.map((c) => relative(REPO, c.path())).filter((p) => /\.html?$/.test(p) && files.includes(p));
    assert.ok(registeredPages.length > 0, 'no registered house-css page is tracked, so this test checks nothing');
    assert.deepEqual(registeredPages.filter((p) => !carriers.includes(p)), [], 'a registered page lost its house-css block');
    assert.deepEqual(carriers.filter((p) => !registered.has(join(REPO, p))), [], 'a house-css block nobody regenerates is a second palette with a generated look');
  });

  test('every generated artefact that declares one names a tracked generator', () => {
    const tracked = new Set(files);
    for (const [artefact, generator] of result.generated) {
      assert.ok(tracked.has(generator), `${artefact} counts through ${generator}, which is not tracked`);
    }
  });
});
